"""Original explanatory SVGs. Coordinates/labels are authored, not external images."""
from pathlib import Path
from html import escape
import json
ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'app/frontend/public/answer-diagrams';OUT.mkdir(exist_ok=True)
def svg(name,title,body):
    text=f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 800 300" role="img" aria-labelledby="title desc"><title id="title">{escape(title)}</title><desc id="desc">{escape(title)}. Original educational diagram; schematic, not measured data.</desc><defs><marker id="arrow" markerWidth="10" markerHeight="8" refX="9" refY="4" orient="auto"><path d="M0 0L10 4L0 8" fill="#365d87"/></marker></defs><rect width="800" height="300" rx="16" fill="#f4f8fc"/><g font-family="sans-serif" fill="#172b45" font-size="17"><text x="30" y="35" font-size="21" font-weight="bold">{escape(title)}</text>{body}</g></svg>'''
    (OUT/f'{name}.svg').write_text(text+'\n')
def box(x,y,w,label,color='#e1edfa'):
 return f'<rect x="{x}" y="{y}" width="{w}" height="55" rx="8" fill="{color}" stroke="#6685a6"/><text x="{x+w/2}" y="{y+33}" text-anchor="middle">{escape(label)}</text>'
def arrow(x,y,xx,yy):
 return f'<path d="M{x} {y}L{xx} {yy}" stroke="#365d87" stroke-width="3" fill="none" marker-end="url(#arrow)"/>'
svg('rope','RoPE: relative position becomes an angle difference',arrow(110,235,280,235)+arrow(110,235,110,65)+arrow(110,235,245,145)+arrow(110,235,185,90)+'<text x="252" y="150">query at m</text><text x="195" y="88">key at n</text><path d="M166 198 Q163 174 143 171" fill="none" stroke="#d1812a" stroke-width="3"/><text x="395" y="115">Rotate each pair by position × frequency.</text><text x="395" y="155">Shared rotation cancels inside the dot product.</text><text x="395" y="195">Remaining angle: (n − m) × frequency</text><text x="395" y="245">Rotation preserves each pair’s norm.</text>')
svg('roofline','Roofline: performance is limited by compute or bandwidth',arrow(80,240,745,240)+arrow(80,240,80,65)+'<path d="M80 240L360 105L720 105" fill="none" stroke="#167d67" stroke-width="5"/><path d="M360 105V240" stroke="#6c8097" stroke-dasharray="6 5"/><text x="90" y="75">FLOPs / second</text><text x="465" y="95">compute ceiling</text><text x="100" y="170">bandwidth-limited</text><text x="395" y="175">compute-limited</text><text x="365" y="276">arithmetic intensity (FLOPs / byte) →</text>')
svg('diffusion','Latent diffusion: learn to reverse noise in compressed space',box(25,100,130,'Image')+arrow(155,127,190,127)+box(195,100,140,'Encoder')+arrow(335,127,370,127)+box(375,100,150,'Latent z₀')+arrow(525,127,560,127)+box(565,100,210,'Add noise → zₜ')+box(365,210,170,'Denoise steps','#dcefe8')+arrow(670,155,535,232)+arrow(365,237,330,237)+box(170,210,155,'Decoder')+arrow(170,237,150,237)+box(25,210,120,'New image')+'<text x="30" y="80">Training: encode real images and corrupt their latents.</text><text x="30" y="188">Generation starts from noise; denoising is conditioned on text or other inputs.</text>')
# A separate layout avoids overlapping the collider caption and nodes.
svg('causal','Causal paths: confounder, mediator, collider',box(20,100,65,'A')+box(205,100,65,'B')+box(110,55,65,'C')+arrow(110,90,80,103)+arrow(175,90,207,103)+'<text x="30" y="205">Adjust C to block</text><text x="30" y="231">this backdoor path.</text>'+box(290,100,65,'A')+box(385,100,65,'M')+box(480,100,65,'B')+arrow(355,127,380,127)+arrow(450,127,475,127)+'<text x="300" y="205">M carries part of</text><text x="300" y="231">A’s effect on B.</text>'+box(560,100,65,'A')+box(650,160,65,'Z')+box(725,100,65,'B')+arrow(605,155,650,175)+arrow(750,155,715,175)+'<text x="565" y="255">Conditioning on Z</text><text x="565" y="280">opens association.</text>')
svg('rag','RAG: evidence must survive each stage',box(20,100,130,'Question')+arrow(150,127,180,127)+box(185,100,165,'Retrieve + ACL')+arrow(350,127,380,127)+box(385,100,165,'Rerank evidence')+arrow(550,127,580,127)+box(585,100,185,'Generate + cite')+'<text x="30" y="200">Check recall</text><text x="235" y="200">Check permissions</text><text x="450" y="200">Check support for each claim</text><text x="30" y="250">A fluent answer cannot repair evidence that was never retrieved.</text>')
svg('speculative','Speculative decoding: verify the proposal distribution',box(20,90,160,'Draft token x')+arrow(180,117,215,117)+box(220,90,290,'Accept: min(1, p(x) / q(x))')+arrow(510,117,555,90)+box(560,63,210,'Accept x','#dcefe8')+arrow(510,117,555,180)+box(560,155,210,'Reject + resample')+'<text x="25" y="220">Accepted mass: min(p, q)</text><text x="380" y="220">Residual mass: max(p − q, 0)</text><text x="25" y="265">Together they recover p. After rejection, stop verifying the old draft suffix.</text>')
for number,name,caption in [(605,'rope','Rotations preserve norm and encode relative displacement.'),(684,'roofline','Ideal attainable performance is the lower of compute and bandwidth ceilings.'),(653,'rag','A grounded answer needs relevant, permitted evidence and claim-level support.'),(724,'rag','Retrieval and generation require separate quality checks.'),(614,'speculative','Acceptance and residual sampling recover the target distribution.'),(1080,'causal','Conditioning has different consequences for common causes, mediators, and colliders.')]:
 path=ROOT/f'app/content/solutions/q{number}.json';d=json.loads(path.read_text())
 if f'/answer-diagrams/{name}.svg' not in d['answer']:d['answer']+=f'\n\n![{caption}](/answer-diagrams/{name}.svg)'
 path.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
print('6 original SVG diagrams linked to 9 answers')
